<title>Friend sentiment around subway ads</title>
<style>
  body { background: transparent; color: var(--text); margin: 0; font-family: system-ui, sans-serif; }
  * { box-sizing: border-box; }
  .wrap { width: 100%; max-width: 740px; margin: 0 auto; padding: 18px 16px 14px; }
  h1 { margin: 0; font-size: 20px; line-height: 1.25; font-weight: 680; }
  .subtitle { margin: 5px 0 14px; color: var(--muted); font-size: 13px; }
  .chart-shell { position: relative; border: 1px solid var(--border); background: var(--panel); border-radius: 12px; padding: 8px 8px 4px; }
  svg { display: block; width: 100%; height: auto; overflow: visible; }
  .legend { display: flex; flex-wrap: wrap; gap: 16px; padding: 7px 12px 10px; color: var(--text); font-size: 12px; }
  .legend-item { display: inline-flex; align-items: center; gap: 6px; }
