  .tooltip strong { display: block; margin-bottom: 3px; font-size: 12px; }
  .tooltip .detail { color: var(--muted); }
</style>
</head>
<body>
<main class="wrap">
  <h1>Friend sentiment around subway ads</h1>
  <p class="subtitle">Weekly stored mentions · Sep 8–Nov 17, 2025</p>
  <section class="chart-shell" aria-label="Weekly stacked sentiment chart">
    <svg id="chart" viewBox="0 0 700 410" role="img" aria-label="Weekly stacked bars of positive, neutral, and negative stored mentions"></svg>
    <div class="tooltip" id="tooltip" role="status" aria-live="polite">
      <strong id="tip-title"></strong>
      <div class="detail" id="tip-detail"></div>
    </div>
    <div class="legend" aria-label="Legend">
      <span class="legend-item"><i class="swatch" style="background:var(--positive)"></i>Positive</span>
      <span class="legend-item"><i class="swatch" style="background:var(--neutral)"></i>Neutral</span>
      <span class="legend-item"><i class="swatch" style="background:var(--negative)"></i>Negative</span>
      <span class="legend-item"><i class="swatch" style="background:var(--accent)"></i>Campaign launch</span>
    </div>
  </section>
</main>
<script>
(() => {
  const data = [
    {date:"2025-09-08", positive:1, neutral:0, negative:6},
    {date:"2025-09-15", positive:0, neutral:0, negative:1},
    {date:"2025-09-22", positive:0, neutral:2, negative:6},
    {date:"2025-09-29", positive:0, neutral:3, negative:5},
    {date:"2025-10-06", positive:0, neutral:1, negative:7},
    {date:"2025-10-13", positive:0, neutral:0, negative:4},
    {date:"2025-10-20", positive:0, neutral:0, negative:6},
    {date:"2025-10-27", positive:0, neutral:1, negative:0},
    {date:"2025-11-03", positive:0, neutral:0, negative:1},
    {date:"2025-11-10", positive:0, neutral:1, negative:1},
    {date:"2025-11-17", positive:0, neutral:2, negative:2}
  ];
  const svg = document.getElementById("chart");
  const ns = "http://www.w3.org/2000/svg";
  const colors = {
    positive: "var(--positive)",
    neutral: "var(--neutral)",
    negative: "var(--negative)",
    accent: "var(--accent)",
    muted: "var(--muted)",
    text: "var(--text)",
    border: "var(--border)"
  };
  const plot = {left: 62, right: 682, top: 30, bottom: 330};
  const maxY = 10;
  const start = Date.parse("2025-09-08T00:00:00Z");
  const end = Date.parse("2025-11-17T00:00:00Z");
  const xFor = date => plot.left + (Date.parse(date + "T00:00:00Z") - start) / (end - start) * (plot.right - plot.left);
  const yFor = value => plot.bottom - value / maxY * (plot.bottom - plot.top);

  function el(name, attrs = {}, parent = svg) {
    const node = document.createElementNS(ns, name);
    for (const [key, value] of Object.entries(attrs)) node.setAttribute(key, String(value));
    parent.appendChild(node);
    return node;
  }
  function text(x, y, content, attrs = {}) {
    const node = el("text", {x, y, ...attrs});
    node.textContent = content;
    return node;
  }

  for (let tick = 0; tick <= maxY; tick += 2) {
    const y = yFor(tick);
    el("line", {x1:plot.left, y1:y, x2:plot.right, y2:y, stroke:colors.border, "stroke-width":1, opacity: tick === 0 ? .9 : .55});
    text(plot.left - 10, y + 4, String(tick), {fill:colors.muted, "font-size":11, "text-anchor":"end"});
  }
  el("line", {x1:plot.left, y1:plot.top, x2:plot.left, y2:plot.bottom, stroke:colors.border, "stroke-width":1});
  el("line", {x1:plot.left, y1:plot.bottom, x2:plot.right, y2:plot.bottom, stroke:colors.border, "stroke-width":1});
  text(17, (plot.top + plot.bottom) / 2, "Mentions", {fill:colors.muted, "font-size":12, "text-anchor":"middle", transform:`rotate(-90 17 ${(plot.top + plot.bottom) / 2})`});
  text((plot.left + plot.right) / 2, 382, "Week starting", {fill:colors.muted, "font-size":12, "text-anchor":"middle"});

  const monthNames = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  const dateLabel = iso => {
    const d = new Date(iso + "T00:00:00Z");
    return monthNames[d.getUTCMonth()] + " " + d.getUTCDate();
  };
  const tooltip = document.getElementById("tooltip");
  const tipTitle = document.getElementById("tip-title");
  const tipDetail = document.getElementById("tip-detail");
  const shell = document.querySelector(".chart-shell");
  function showTip(event, title, detail) {
    tipTitle.textContent = title;
    tipDetail.textContent = detail;
    tooltip.style.display = "block";
    const rect = shell.getBoundingClientRect();
    const px = event.clientX ? event.clientX - rect.left : 0;
    const py = event.clientY ? event.clientY - rect.top : 0;
    tooltip.style.left = Math.max(8, Math.min(px + 12, rect.width - 245)) + "px";
    tooltip.style.top = Math.max(8, Math.min(py + 10, rect.height - 76)) + "px";
  }
  function hideTip() { tooltip.style.display = "none"; }

  data.forEach((week, index) => {
    const x = xFor(week.date);
    const width = 34;
    let cumulative = 0;
    const total = week.positive + week.neutral + week.negative;
    for (const key of ["positive", "neutral", "negative"]) {
      const count = week[key];
      if (!count) continue;
      const yTop = yFor(cumulative + count);
      const yBottom = yFor(cumulative);
      const rect = el("rect", {
        x:x - width / 2, y:yTop, width, height:yBottom - yTop,
        fill:colors[key], rx:2, tabindex:0, role:"img",
        "aria-label":`${dateLabel(week.date)}: ${count} ${key} mentions`
      });
      const title = `${dateLabel(week.date)} · ${key.charAt(0).toUpperCase() + key.slice(1)}`;
      const detail = `${count} ${key} mention${count === 1 ? "" : "s"} · ${total} total that week`;
      rect.addEventListener("pointerenter", event => showTip(event, title, detail));
      rect.addEventListener("pointermove", event => showTip(event, title, detail));
      rect.addEventListener("pointerleave", hideTip);
      rect.addEventListener("focus", event => showTip(event, title, detail));
      rect.addEventListener("blur", hideTip);
      cumulative += count;
    }
    text(x, plot.bottom + 21, dateLabel(week.date), {
      fill:colors.muted, "font-size":10.5, "text-anchor":"middle"
    });
  });

  const campaignX = xFor("2025-09-26");
  el("line", {
    x1:campaignX, y1:plot.top, x2:campaignX, y2:plot.bottom,
    stroke:colors.accent, "stroke-width":2, "stroke-dasharray":"5 4"
  });
  text(campaignX + 5, 17, "Sep 26 · Subway campaign launch", {
    fill:colors.accent, "font-size":10.5, "font-weight":650
  });
})();
</script>
</body>
</html>"}

