<body>
<main class="wrap">
  <h1>Top Friend themes by sentiment</h1>
  <p class="sub">2025-09-08 – 2025-11-22 · Sorted by precomputed theme totals</p>
  <div class="chart-box" id="chartBox">
    <svg id="chart" viewBox="0 0 700 552" role="img" aria-label="Horizontal stacked bar chart of the top 12 Friend themes, split by sentiment"></svg>
  </div>
  <p class="note">Bar segments count sentiment-tagged mention records in the supplied list; the right-hand value is the precomputed theme total. The evidence list may not contain every mention counted in that total.</p>
</main>
<div class="tooltip" id="tooltip" role="status" aria-live="polite"></div>
<script>
"use strict";

const themeCounts = {
  "privacy":27,"user experience":1,"social awkwardness":3,"founder response":1,
  "personality":1,"product criticism":1,"review":1,"social reaction":2,
  "chatbot personality":2,"technical problems":1,"loneliness":11,"social norms":1,
  "usability":1,"ai personality":1,"ad campaign":33,"marketing strategy":2,
  "backlash":4,"orders":1,"credibility":1,"vandalism":11,"surveillance":7,
  "spending":1,"public reaction":1,"publicity":2,"public backlash":1,"marketing":1,
  "human connection":10,"sales":1,"AI companionship":1,"price and sales":1,
  "product usefulness":1,"emotional dependency":1,"protest":3,"product reviews":2,
  "brand parody":1,"product review":1,"companionship":2,"ai companionship":3,
  "founder interview":1,"product":1,"ai backlash":1,"product experience":1,
  "wearable ai":1,"product features":1,"ai wearables":1,"product category":1,"reviews":1
};

/* Theme tags below are the exact matching theme names from the supplied mention records. */
const records = [
  ["negative",["social awkwardness"]],
  ["negative",["social awkwardness"]],
  ["negative",["social reaction","chatbot personality"]],
  ["negative",["social awkwardness"]],
  ["negative",["social reaction","chatbot personality"]],
  ["neutral",["ad campaign","backlash"]],
