  ["negative",["human connection","ad campaign"]],
  ["negative",["loneliness"]],
  ["negative",["ad campaign","surveillance"]],
  ["negative",["loneliness","human connection","ad campaign"]],
  ["negative",["protest","ad campaign"]],
  ["negative",["ad campaign","human connection"]],
  ["negative",["loneliness","ad campaign","human connection"]],
  ["negative",["protest","human connection"]],
  ["negative",["protest","human connection"]],
  ["negative",[]],
  ["negative",["loneliness","human connection","ad campaign"]],
  ["neutral",[]],
  ["neutral",["ai companionship"]],
  ["negative",["ad campaign"]],
  ["negative",["ai companionship","loneliness","human connection","ad campaign"]],
  ["negative",["ai companionship","human connection","ad campaign"]],
  ["neutral",["ad campaign"]]
];

const evidence = {
  "ad campaign": {
    date:"2025-09-26", source:"newsbreak.com",
    url:"https://www.newsbreak.com/adweek-310357647/4259016973624-ai-startup-friend-bets-on-foes-with-1m-nyc-subway-campaign",
    title:"AI Startup Friend Bets On Foes With $1M NYC Subway Campaign",
    summary:"Adweek reports that Friend covered subway cars and stations across New York with a large-scale campaign for its AI companion pendant. Founder Avi Schiffmann said the campaign was intended to invite social commentary, and the stark, open poster design drew graffiti and criticism from riders."
  },
  "privacy": {
    date:"2025-09-08", source:"wired.com",
    url:"https://www.wired.com/story/i-hate-my-ai-friend/",
    title:"I Hate My Friend",
    summary:"WIRED writers Kylie Robison and Boone Ashworth recount testing Friend over several weeks. The device’s always-on listening made people around Robison uneasy, while the chatbot’s sarcastic replies and connectivity problems frustrated Ashworth. The review questions whether the pendant can serve as a companion when wearing it can feel antisocial."
  },
  "loneliness": {
    date:"2025-09-12", source:"opentools.ai",
    url:"https://opentools.ai/news/ai-necklace-friend-sparks-privacy-outrage-and-social-backlash",
    title:"AI Necklace 'Friend' Sparks Privacy Outrage and Social Backlash",
    summary:"This OpenTools article summarizes Friend’s intended role as an AI companion and the concerns raised about its always-on audio capture. It says the device’s deliberately moody personality adds to criticism that it feels invasive and socially awkward. The article presents privacy and social norms as central reasons for the negative reception."
  },
  "vandalism": {
    date:"2025-09-27", source:"techcrunch.com",
    url:"https://techcrunch.com/2025/09/27/ai-startup-friend-spent-more-than-1m-on-all-those-subway-ads/",
    title:"AI startup Friend spent more than $1M on all those subway ads",
    summary:"TechCrunch reports that Friend’s campaign included more than 11,000 subway-car cards, 1,000 platform posters, and 130 urban panels. It notes the high cost and Schiffmann’s description of the buy as a gamble, alongside graffiti criticizing the pendant as surveillance and urging people to find real friends."
  },
  "human connection": {
    date:"2025-10-07", source:"gothamist.com",
    url:"https://gothamist.com/arts-entertainment/the-guy-behind-those-friend-ads-in-the-subways-is-tired-of-talking-to-new-yorkers",
    title:"The guy behind those ‘Friend’ ads in the subways is tired of talking to New Yorkers",
    summary:"Ryan Kailath describes the spread of Friend’s ads and the graffiti opposing them, including messages urging people to make real friends. Commuter Tricia Hersey objects that the device and campaign encourage individualism at the expense of community, while founder Avi Schiffmann says the ad design left space for public comments but declines to speak with riders during the reported visit."
  },
  "surveillance": {
    date:"2025-09-27", source:"techbuzz.ai",
    url:"https://www.techbuzz.ai/articles/friend-ai-startup-bets-1m-on-nyc-subway-ads-despite-backlash",
    title:"Friend AI Startup Bets $1M on NYC Subway Ads Despite Backlash",
    summary:"The Tech Buzz says Friend blanketed the transit system with ads for its $129 AI pendant and describes the expenditure as a high-stakes gamble for the startup. It highlights riders’ graffiti and objections to a wearable that listens throughout the day, while noting Schiffmann intended the campaign’s blank space to invite public commentary."
  },
  "backlash": {
    date:"2025-09-26", source:"newsbreak.com",
    url:"https://www.newsbreak.com/adweek-310357647/4259016973624-ai-startup-friend-bets-on-foes-with-1m-nyc-subway-campaign",
    title:"AI Startup Friend Bets On Foes With $1M NYC Subway Campaign",
    summary:"Adweek reports that Friend covered subway cars and stations across New York with a large-scale campaign for its AI companion pendant. Founder Avi Schiffmann said the campaign was intended to invite social commentary, and the stark, open poster design drew graffiti and criticism from riders."
  },
  "social awkwardness": {
    date:"2025-09-08", source:"wired.com",
    url:"https://www.wired.com/story/i-hate-my-ai-friend/",
    title:"I Hate My Friend",
    summary:"WIRED writers Kylie Robison and Boone Ashworth recount testing Friend over several weeks. The device’s always-on listening made people around Robison uneasy, while the chatbot’s sarcastic replies and connectivity problems frustrated Ashworth. The review questions whether the pendant can serve as a companion when wearing it can feel antisocial."
  },
  "protest": {
    date:"2025-10-22", source:"semasocial.com",
    url:"https://semasocial.com/blog/friend-ai-creator-sparks-nyc-friend-protest",
    title:"Friend AI Creator Sparks NYC ‘Friend Protest’",
    summary:"This article recounts a gathering where protesters defaced a Friend banner and criticized the notion of an AI pendant as a companion. It says the subway campaign and negative early reviews helped fuel concerns about intrusive listening and AI displacing human relationships. The piece also reports that Schiffmann attended and spoke with critics, drawing a mix of skepticism and respect."
  },
  "ai companionship": {
    date:"2025-11-19", source:"mancunion.com",
    url:"https://mancunion.com/opinion/ai-could-be-useful-for-lots-of-things-but-being-your-best-friend-isnt-one-of-them",
    title:"AI could be useful for lots of things but being your best friend isn't one of them",
    summary:"Mancunion opinion writer Constance Mason says Friend records users’ conversations and sends responses through an app, with possible benefits for people who struggle to start social interactions. But she argues it treats loneliness as an individual problem rather than addressing the lack of community, and could discourage real relationships; she also points to the vandalized subway ads as evidence."
  },
  "social reaction": {
    date:"2025-09-08", source:"niemanlab.org",
    url:"https://www.niemanlab.org/reading/i-hate-my-friend/",
    title:"I hate my Friend",
    summary:"Nieman Journalism Lab included WIRED’s review in its September 8 reading roundup. The excerpt notes that the microphone-packed pendant may raise privacy concerns, upset people around its wearer, and even draw hostile replies from its own chatbot. The mention is brief and directs readers to the original review."
  },
  "chatbot personality": {
    date:"2025-09-08", source:"niemanlab.org",
    url:"https://www.niemanlab.org/reading/i-hate-my-friend/",
    title:"I hate my Friend",
    summary:"Nieman Journalism Lab included WIRED’s review in its September 8 reading roundup. The excerpt notes that the microphone-packed pendant may raise privacy concerns, upset people around its wearer, and even draw hostile replies from its own chatbot. The mention is brief and directs readers to the original review."
  }
};

const palette = {
  positive: getComputedStyle(document.body).getPropertyValue("--positive").trim() || "#348b68",
  neutral: getComputedStyle(document.body).getPropertyValue("--neutral").trim() || "#8b929d",
  negative: getComputedStyle(document.body).getPropertyValue("--negative").trim() || "#c45b5b"
};
const sentiments = ["positive","neutral","negative"];
const themes = Object.entries(themeCounts).map(([name,total],i)=>({name,total,i}))
  .sort((a,b)=>b.total-a.total || a.i-b.i).slice(0,12);

for (const theme of themes) {
  theme.counts = {positive:0,neutral:0,negative:0};
  for (const row of records) {
    if (row[1].includes(theme.name)) theme.counts[row[0]]++;
  }
  theme.observed = sentiments.reduce((sum,s)=>sum+theme.counts[s],0);
}
const maxObserved = Math.max(...themes.map(t=>t.observed),1);
const svg = document.getElementById("chart");
const NS = "http://www.w3.org/2000/svg";
function el(tag, attrs, text) {
  const n = document.createElementNS(NS, tag);
  for (const [k,v] of Object.entries(attrs || {})) n.setAttribute(k,String(v));
  if (text !== undefined) n.textContent = text;
  svg.appendChild(n);
  return n;
}
const plot = {x:158, y:127, w:390, row:31};
const chartBottom = plot.y + plot.row * themes.length - 4;
const scale = plot.w / maxObserved;

el("text",{x:plot.x,y:21,class:"axis-label"},"Listed mention records by sentiment");
const legendY = 43;
let legendX = plot.x;
for (const s of sentiments) {
  el("rect",{x:legendX,y:legendY-10,width:10,height:10,rx:2,fill:palette[s]});
  el("text",{x:legendX+15,y:legendY-1,class:"legend-label"},s[0].toUpperCase()+s.slice(1));
  legendX += s === "positive" ? 87 : 83;
}

const tickCount = Math.min(maxObserved,5);
const ticks = new Set([0,maxObserved]);
for (let i=1;i<tickCount;i++) ticks.add(Math.round(maxObserved*i/tickCount));
[...ticks].sort((a,b)=>a-b).forEach(v=>{
  const x=plot.x+v*scale;
  el("line",{x1:x,y1:plot.y-9,x2:x,y2:chartBottom,class:"grid"});
  el("text",{x,y:chartBottom+19,"text-anchor":"middle",class:"tick"},String(v));
});
el("line",{x1:plot.x,y1:chartBottom+2,x2:plot.x+plot.w,y2:chartBottom+2,class:"axis"});
el("text",{x:plot.x+plot.w/2,y:chartBottom+39,"text-anchor":"middle",class:"axis-label"},"Mention records in supplied list");

const tooltip = document.getElementById("tooltip");
function showTooltip(theme, event) {
  const c=theme.counts, ev=evidence[theme.name];
  tooltip.replaceChildren();
  const head=document.createElement("strong");
  head.textContent=theme.name;
  tooltip.appendChild(head);
  const counts=document.createElement("div");
  counts.className="counts";
  counts.textContent=`Listed records — Positive ${c.positive} · Neutral ${c.neutral} · Negative ${c.negative} · Precomputed theme total ${theme.total}`;
  tooltip.appendChild(counts);
  if (ev) {
    const a=document.createElement("a");
    a.href=ev.url;
